function shouldPreserveTextareaResizeStyle(
  el: Element,
  key: string,
  prev: string | string[] | undefined,
  next: string | string[],
): boolean {
  return (
    el.tagName === 'TEXTAREA' &&
    (key === 'width' || key === 'height') &&
    isString(next) &&
    prev === next
  )
}

